# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">GAZLARIN GENEL ÖZELLİKLERİ VE TANECİKLİ YAPISI (10.1.8)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#1e40af">GAZ HALİNİN AYIRT EDİCİ ÖZELLİKLERİ</text>\n  <text x="35" y="88" font-size="11.1" fill="#1e3a8a">• Belirli şekil ve hacimleri yoktur; konuldukları</text>\n  <text x="45" y="104" font-size="10.8" fill="#1e3a8a">kabın tamamını doldurur ve hacmini alırlar.</text>\n  <text x="35" y="128" font-size="11.1" fill="#1e3a8a">• Tanecikler arası boşluk çok fazla olduğu için</text>\n  <text x="45" y="144" font-size="10.8" fill="#1e3a8a">yüksek oranda sıkıştırılabilirler.</text>\n  <text x="35" y="168" font-size="11.1" fill="#1e3a8a">• Yoğunlukları (özkütleleri) katı ve sıvılara göre</text>\n  <text x="45" y="184" font-size="10.8" fill="#1e3a8a">çok düşüktür; akışkandırlar.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#166534">HAREKET, GENLEŞME VE KARIŞABİLİRLİK</text>\n  <text x="370" y="88" font-size="11.1" fill="#14532d">• Tanecikleri titreşim, dönme ve özellikle</text>\n  <text x="380" y="104" font-size="10.8" fill="#14532d">öteleme (yer değiştirme) hareketi yapar (Soygaz</text>\n  <text x="380" y="120" font-size="10.8" fill="#14532d">atomları ise yalnız öteleme hareketi yapar).</text>\n  <text x="370" y="144" font-size="11.1" fill="#14532d">• Sıcaklık etkisiyle aynı oranda genleşirler</text>\n  <text x="380" y="160" font-size="10.8" fill="#14532d">(genleşme katsayıları gazlar için ayırt edici değildir).</text>\n  <text x="370" y="184" font-size="11.1" fill="#14532d">• Birbiriyle her oranda homojen karışırlar (çözelti).</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Gazlar bulundukları kabın her noktasına çarparak eşit büyüklükte ve homojen gaz basıncı uygularlar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">GAZLARI TANIMLAYAN DÖRT TEMEL DEĞİŞKEN VE BİRİMLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#92400e">1. BASINÇ (P) VE 2. HACİM (V)</text>\n  <text x="35" y="88" font-size="11.1" fill="#78350f">• Basınç (P): Birim yüzeye dik etki eden çarpma</text>\n  <text x="45" y="104" font-size="10.8" fill="#78350f">kuvvetidir. Açık hava: Barometre, Kapalı: Manometre.</text>\n  <text x="35" y="126" font-size="10.8" font-weight="bold" fill="#78350f">• 1 atm = 76 cmHg = 760 mmHg = 760 Torr</text>\n  <text x="35" y="150" font-size="11.1" fill="#78350f">• Hacim (V): Gazın hacmi bulunduğu kabın hacmine</text>\n  <text x="45" y="166" font-size="10.8" fill="#78350f">eşittir (sabit hacimli kap veya pistonlu kap).</text>\n  <text x="35" y="188" font-size="10.8" font-weight="bold" fill="#78350f">• 1 L = 1 dm³ = 1000 mL = 1000 cm³ ; 1 m³ = 1000 L</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#6b21a8">3. SICAKLIK (T) VE 4. MADDE MİKTARI (n)</text>\n  <text x="370" y="88" font-size="11.1" fill="#581c87">• Mutlak Sıcaklık (T): Termometre ile ölçülür;</text>\n  <text x="380" y="104" font-size="10.8" fill="#581c87">gaz hesaplamalarında Kelvin (K) birimi kullanılır.</text>\n  <text x="370" y="126" font-size="10.8" font-weight="bold" fill="#581c87">• T (Kelvin) = t (°C) + 273  (0 °C = 273 K)</text>\n  <text x="370" y="150" font-size="11.1" fill="#581c87">• Ortalama kinetik enerji mutlak sıcaklıkla (T)</text>\n  <text x="380" y="166" font-size="10.8" fill="#581c87">doğru orantılıdır.</text>\n  <text x="370" y="188" font-size="10.8" font-weight="bold" fill="#581c87">• Mol Sayısı (n): n = m / Mₐ = N / Nₐ (Nₐ = 6,02·10²³)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Dikkat: Sıcaklığı 25 °C\'den 50 °C\'ye çıkan gazın mutlak sıcaklığı (298 K ⟶ 323 K) iki katına ÇIKMAZ!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KİNETİK MOLEKÜLER TEORİ (KMT) VE MOLEKÜL HIZI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#9a3412">KİNETİK TEORİNİN TEMEL VARSAYIMLARI</text>\n  <text x="35" y="88" font-size="10.8" fill="#7c2d12">• Gaz taneciklerinin öz hacimleri, kabın hacmi</text>\n  <text x="45" y="104" font-size="10.8" fill="#7c2d12">yanında ihmal edilir (noktasal tanecik kabulü).</text>\n  <text x="35" y="128" font-size="10.8" fill="#7c2d12">• Tanecikler her yönde doğrusal, gelişigüzel ve</text>\n  <text x="45" y="144" font-size="10.8" fill="#7c2d12">sürekli hareket eder (Brown hareketi).</text>\n  <text x="35" y="168" font-size="10.8" fill="#7c2d12">• Çarpışmalar tam esnektir (toplam enerji korunur).</text>\n  <text x="35" y="192" font-size="10.8" fill="#7c2d12">• Çarpışma anı dışında itme-çekme kuvveti yok sayılır.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#065f46">DİFÜZYON, EFÜZYON VE İDEAL GAZ</text>\n  <text x="370" y="88" font-size="10.8" fill="#064e3b">• Aynı mutlak sıcaklıkta (T) bulunan tüm gazların</text>\n  <text x="380" y="104" font-size="10.8" fill="#064e3b">ortalama kinetik enerjileri (Eₖ = 3/2 k·T) EŞİTTİR.</text>\n  <text x="370" y="128" font-size="10.8" fill="#064e3b">• Difüzyon (yayılma) ve Efüzyon (boşluğa sızma) hızı:</text>\n  <text x="380" y="146" font-size="10.8" font-weight="bold" fill="#064e3b">v₁ / v₂ = kök( (T₁ · Mₐ₂) / (T₂ · Mₐ₁) )</text>\n  <text x="370" y="170" font-size="10.8" fill="#064e3b">• Gerçek gazlar; YÜKSEK SICAKLIK, DÜŞÜK BASINÇ</text>\n  <text x="380" y="186" font-size="10.8" fill="#064e3b">ve küçük mol kütlesinde (Mₐ) ideale yaklaşır.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Aynı sıcaklıkta mol kütlesi (Mₐ) küçük olan hafif gaz tanecikleri (ör. H₂ ve He) daha hızlı hareket eder.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
